#include<iostream>
#include<vector>
#include<string>
#include <utility> 
#include <sstream>
#include<algorithm>
#include<map>
using namespace std;
​
int main() {
    int minAverageLost;

    cin >> minAverageLost;
    map<int, vector<pair<int, int>>> mp;
    vector<int> ans(100, 0);
    int len = 0;
    int tmp;
​
    while (cin >> tmp) {
        ans[len++] = tmp;
    }
    int currentLen = 0;
    vector<int> prefix(len+ 1, 0);
    // 前缀和数组构造
    for (int i = 1; i <= len; i++) {
        prefix[i] = prefix[i-1] + ans[i-1];
    }
    // 计算结果
    for (int i = 0; i <= len; i++) {
        for (int j = i + 1 ; j <= len; j++) {
            if (j - i < currentLen) {
                continue;
            }
            int sum = prefix[j] - prefix[i];
            if (sum  * 1.0 / (j-i) <= minAverageLost){
                currentLen = max(currentLen, j - i);
                mp[currentLen].push_back({i, j-1});
            }   
        }
    }

    if (currentLen == 0) {
        cout<< "NULL";
        return 0;
    }
    // 输出结果
    vector<pair<int, int>> maxLenV = mp[currentLen];
    for (int i = 0; i < maxLenV.size(); i++) {
        if (i !=0) {
            cout << " ";
        }
        pair<int, int> p = maxLenV[i];
        cout<< p.first << "-"<<p.second;
    }
    return 0;
}
