rl.on("close", () => {
    if (inputData.length < 2) {
        console.log("NULL");
        return;
    }
​
    const minAverageLost = parseInt(inputData[0]); // 第一行的数值
    const ans = inputData[1].split(/\s+/).map(Number); // 第二行解析成数组
    const len = ans.length;
​
    if (len === 0) {
        console.log("NULL");
        return;
    }
​
    // 计算前缀和
    const prefix = new Array(len + 1).fill(0);
    for (let i = 1; i <= len; i++) {
        prefix[i] = prefix[i - 1] + ans[i - 1];
    }
​
    let currentLen = 0;
    const mp = new Map();
​
    // 计算最长子区间
    for (let i = 0; i <= len; i++) {
        for (let j = i + 1; j <= len; j++) {
            if (j - i < currentLen) continue;
            const sum = prefix[j] - prefix[i];
            if (sum / (j - i) <= minAverageLost) {
                currentLen = Math.max(currentLen, j - i);
