package main
​
import (
    "bufio"
    "fmt"
    "os"
    "strconv"
    "strings"
)
​
func main() {
    scanner := bufio.NewScanner(os.Stdin)
​
    // 读取第一行
    scanner.Scan()
    minAverageLost, _ := strconv.Atoi(scanner.Text())
​
    // 读取第二行
    if !scanner.Scan() {
        fmt.Println("NULL")
        return
    }
​
    // 解析第二行的数字
    numsStr := strings.Fields(scanner.Text())
    var ans []int
    for _, num := range numsStr {
        val, _ := strconv.Atoi(num)
        ans = append(ans, val)
    }
​
    lenAns := len(ans)
    if lenAns == 0 {
        fmt.Println("NULL")
        return
    }
​
    // 计算前缀和
    prefix := make([]int, lenAns+1)
    for i := 1; i <= lenAns; i++ {
        prefix[i] = prefix[i-1] + ans[i-1]
    }
​
    currentLen := 0
    mp := make(map[int][][]int)
​
    // 计算最长子区间
    for i := 0; i <= lenAns; i++ {
        for j := i + 1; j <= lenAns; j++ {
            if j-i < currentLen {
                continue
            }
            sum := prefix[j] - prefix[i]
            if float64(sum)/float64(j-i) <= float64(minAverageLost) {
                currentLen = max(currentLen, j-i)
                mp[currentLen] = append(mp[currentLen], []int{i, j - 1})
            }
        }
    }
​
    if currentLen == 0 {
        fmt.Println("NULL")
        return
    }
​
    // 输出结果
    var result []string
    for _, pair := range mp[currentLen] {
        result = append(result, fmt.Sprintf("%d-%d", pair[0], pair[1]))
    }
    fmt.Println(strings.Join(result, " "))
}
​
// 计算最大值
func max(a, b int) int {
    if a > b {
        return a
    }
    return b
}
